      "[1]\nҰ[G]лы Құдай, Әкелік [C]мейіріммен,\nСый[D]ға тартып, нұры[D7]ңды тө[G]ккенде,\nӨз қолыңмен Жаратушым жасаған,\nБар тіршілік, әлемді көргенде.\n\n[Қр.]\nТәңі[G]рім, со[C]нда Саған рухым жырл[G]айды:\nҰлы[Am]сың С[D7]ен! [G]Ұлысың Сен!.\n\n[2]\nАспанға, жұлдыздарға көз салсам мен,\nҒажайып жарқын әлем жүзіне.\nМұхиттағы кемедей жүзіп жүрген,\nАй мен күнді әуеде көргенде.\n\n[3]\nЖаратылыс көктемде құлпырғанда,\nЖұпар иісі кеудеме толғанда,\nБұлбұл әнін тоғайда естігенде,\nБұлақтың сылдырын тыңдағанда.\n\n[4]\nКүн күркіреп, найзағай жарқ еткенде,\nҮстімізден қара бұлт төнгенде,\nКемпірқосақ назарыма түскенде,\nҚұнарсыз жерге жауын жауғанда.\n\n[5]\nАдамзатты сүйіп жер бетіндегі,\nҚайғы-қасіреттен құтқарғанда,\nМейір төгіп, жасаған қасиетті,\nІстері туралы оқығанда.\n\n[6]\nБұл дүниеде адамға үлгі болған.\nМәсіхтің жуас жүзін көргенде,\nАйқышта кешірімін беремін деп,\nБар әлемнің Патшасы өлгенде.\n\n[7]\nЖүрегімді құмарлық жайлағанда,\nБар қайғы-мұң жанға батқанында,\nМейіріммен басып Өз кеудесіне,\nЖылы сөзбен мені Ол жұбатар.\n\n[8]\nИса мені Өзіне шақырғанда,\nНұрын шашып, сәулесі жарқырап,\nСонда рухым үн шығармай қалады,\nҰлылығын Құдайдың мойындап.\n\n[Қр.]\nҚұдайымызды ән-жырмен мадақтау игі,\nБұл қандай ұнамды да жарасымды!",
