    storage_path: null,
    duration_seconds: 325,
    lyrics:
      "О, киелі түн,\nЖұлдыздар жарқыраған,\nҒажап түн,\nМәсіх келді дүниеге.\n\nӘлем батты\nЗаңсыздық пен күнәға,\nҚұдай Ұлы\nҚұтқару берді бізге.\n\nЖүрек тола\nҮміт пен қуанышқа,\nБолашақ нұры\nЖетелер алға.\n\nТізеңді бүк,\nПеріштенің үнін тыңда!\nО, ғажап түн,\nКиелі Мәсіх туған!\n\nОл үйретті\nСүюді махаббатпен,\nТыныштық,\nРақымың жаудырып.\n\nБақытсыз бен\nҚасірет шеккендерге\nӨмір берді,\nАйқышта құрбан болып.\n\nӘніміз Оны\nДаңқтап дәріптесін,\nӘркім Құдайға\nҚуанып келсін!\n\nТізеңді бүк,\nПеріштенің үнін тыңда!\nО, ғажап түн,\nИса Мәсіх туған!",
