    storage_path: null,
    duration_seconds: 239,
    lyrics:
      "Жүрек көзін ашшы, Ием,\nЖүрек көзін ашшы, Ием,\nКөргім келеді,\nКөргім келеді.\n\nЖүректегі бар сырымды\nТыңдашы Сен, жалықпай.\nЖүрейін еркін,\nМен қамықпай.\n\nЖүрегіме сабыр берші,\nЖаныма жақын келші,\nСезгім келеді,\nСенгім келеді.\n\nЖетелеші арманыма,\nӨзіңнің ақ жолыңа,\nСенгім келеді,\nЕргім келеді.\n\nНұр шашқан салтанатыңды\nКөргім келеді мен даңқыңды!\nТолып махаббатыңа\nӘндетем киелі, киелі, киелі!\n\nКиелі, киелі, киелі\nБолғым келеді!",
