    storage_path: null,
    duration_seconds: 276,
    lyrics:
      "О, Құдай, Иса Ием менің,\nТек Саған өмірімді арнаймын!\nЫмырттың, сәттің жүзінде, тынысымда\nАңсаймын: «Әке, Әке, Әке» деп,\nДүрсілдейді жүрегім.\n\nТәңірім, Сенің алдыңда басымды ием,\nЖалғыз тілегім — Сенің Рухыңа кенелемін мен!\nТәңірім, Сенің алдыңда басымды ием,\nСені сүйемін! Сенің қолыңда менің жүрегім!\n\nСенің қолыңда менің жүрегім,\nСенің қолыңда менің өмірім!\nСенің қолыңда менің жүрегім,\nСенің қолыңда менің өмірім!",
