    permission_note: "Permitted for community worship sharing",
    audio_url: "/audio/qandai-ghazhaiyp-esiming.mp3",
    storage_path: null,
    duration_seconds: 300,
    lyrics:
      "Әуел баста Өзің орнаттың\nСөзіңмен айтып бәрін.\nКүлістерің шапағатты,\nПатшалығың мәңгілік!\n\nҚандай ғажайып есімің,\nҚандай ғажайып есімің,\nИса Мәсіх, Ұлы Патша!\nҚандай ғажайып, Тәңірім,\nЕшкім тең келмейтін,\nҚандай ғажайып есімің,\nИса Мәсіх!\n\nБізсіз аспанда қаламадың,\nСен біз үшін көктен келдің.\nРақымыңмен күнәмді кештің,\nБоламыз мәңгі бірге!\n\nӨлімді жеңіп, қайта тірілдің,\nКүнә мен өлім жеңілді!\nЖеңімпаз Ием, мәңгіге Сені\nМадақтайды ұлың мен қызың!\n\nСенде патшалық,\nСенде салтанат,\nҚазір әрі келер күнде!\nБар билік Сенде,\nБар күш те Сенде,\nСенің есімің керемет!",
