    audio_url: "/audio/ya-znayu-kto-ya-v-tebe.m4a",
    storage_path: null,
    duration_seconds: 329,
    lyrics:
      "Кто же я, что Всевышний Царь\nМеня признал?\nЯ блуждал, но любовь Твоя\nМеня нашла,\nО, меня нашла!\n\nДал свободу мне\nИисус навек,\nЯ дитя Царя,\nЗнаю я!\n\nЯ свободен, искуплен Им,\nУ милости.\nБыл я в рабстве греха, но Ты\nЖизнь отдал\nЗа мои грехи!\n\nДал свободу мне\nИисус навек,\nЯ дитя Царя,\nЗнаю я!\nВ доме есть всегда\nМесто для меня,\nЯ дитя Царя,\nЗнаю я!\n\nБогом избран, не оставлен,\nЯ знаю, кто я в Тебе!\nТвоим другом был я назван,\nЯ знаю, кто я в Тебе!",
