    duration_seconds: 207,
    lyrics:
      "Здесь не будет шума,\nСлов пустых не нужно,\nПусть звучит Тебе хвала!\nНе стремлюсь я в песне\nОкунуться в чувства,\nЯ пою лишь для Тебя!\n\nВсем сердцем жажду я,\nЕсли петь, то для Тебя!\nПеть всесильно для Царя!\nЯ не могу найти\nНикаких других причин,\nЛишь Тебя превозносить!\n\nВозжелал Ты сердце\nВместо славы жертв,\nВсё, что есть, Тебе отдам!\nЦеннее всех песен,\nНедолговечных,\nСтрасть дала сердца поклонение.\nПусть моя песня\nЗвучит лишь с целью:\nВедь Ты достоин славы всей, Бог!",
