    lyrics:
      "Ты все осколки разбитой жизни\nСобрал и склеил по милости.\nЯ потерял всё, но Ты не бросил,\nНавек меня освободил!\n\nО, благодать, как ты сладка,\nСпасла меня лишь ты!\nО, потерян был, но ты нашла,\nОткрыв глаза мои!\nО, вижу я Тебя,\nЛюбовь в Твоих глазах вижу я!\nТы жизнь Свою отдал,\nЧтоб к жизни всех разбитых призвать!\n\nЗабрав падения и недостатки,\nСвою Ты ценность в нас поместил.\nВ моём Ты сердце, я — Твой сосуд, Бог,\nПусть видит мир: во мне Ты жив!",
