    lyrics:
      "Әрбір арманымды беремін,\nАлдыңа әкеп Сенің тағыңның.\nӨмірімде жалғыз панам да —\nӨзгермейді махаббатың Сенің!\n\nКүрескен келді өмірім үшін,\nҚалжырап қалдым, кетті бар күшім.\nМақтау, жауынгер, жеңімпаз Патшам,\nЖеңіске жетем, менің жақтаушым!\n\nТауларды қозғалтпасаң\nҚалағанымдай мен,\nТеңізді Сен ашпасаң\nАлдымда тулаған,\nЕгер жауап қатпасаң\nЖалбарынғанда мен,\nСенемін, сенемін,\nСенемін Саған!\n\nЕртеңгі күн әкелер нені,\nБәрін білесің, белгілі бәрі.\nМенің өмірім — демімсің менің,\nЖолыңмен жүрем Сенің әр күні.\n\nТыныштығым мен күшім,\nСүйенішімсің Сен!\nСен менің негізімсің,\nБерік жартасымсың!\nҒажап жолдарың Сенің\nБәрінен жоғары,\nБүкіл әлем қолыңда,\nБәрінің Иесі!",
