    lyrics:
      "[1]\nС[Em]иынғанда, си[C]ынғанда\n[Am]Құдаймен[B7]ен сөйле[Em]сем,\nҚ[Em]иналғанда, түн б[C]олса да,\n[Am]Ұйықтамастан [B7]сиын[Em]ам.\nЖа[Am]ратқанның а[D]лдында,\nМ[G]ен тізерлеп қол [Em]созып,\n[Am]Бар қай[D]ғымды а[G]йтып жалынды[E]м:\n[Am]О, Құдайым, мені ұ[D]қсаң,\nТ[G]ек Сенен күш [Em]сұраймын.\n[Am]Күшім кетіп, т[B7]ұрмын әлсі[Em]реп.\n\n[2]\nСыртта қатты дауыл ұрып,\nБет қаратпас мұздай қар.\nДәл осындай боран болып,\nЖүрегімді сыздатты.\nӘлсіздігімді сезіп,\nКөзімнен жас құйылып,\nМен Исаға тұрып жалындым:\nСен білесің, Құдайым,\nЖүректегі қайғымды,\nТұңғиықтан қайтып шығам мен?\n\n[3]\nЖеңіл-желпі оңай өмір,\nТілемеймін Тәңірім,\nҚасіреті, қайғысы мол,\nБолса-дағы жолымның.\nТілеймін мен бір ғана:\nӘрдайым сезіп тұрсам,\nСенің құдіретті қолыңды,\nШырмалынған жолдардан,\nЖағаласқан жаулардан\nӨзің алып шығасың Құдай.\n\n[4]\nСиынғанда, сиынғанда,\nРазы болып, қуанам.\nДаңқтап Сенің рақымыңды,\nҚұдіретті күшіңді.\nКүш күткенде әлсіреп,\nАзғындыққа алданып,\nМен жығылдым қарсы тұра алмай.\nЖүректен шыққан күйік,\nСаған жетті Құдайым,\nСиынып Сенен қуат алдым.",
